            { "sid": "a6", "kind": "mutex_unlock", "resource": "main::m1" },
            { "sid": "a7", "kind": "return" }
          ]
        },
        {
          "name": "b",
          "kind": "normal",
          "form": "closure",
          "body": [
            { "sid": "b1", "kind": "mutex_lock", "resource": "main::m2" },
            { "sid": "b2", "kind": "semaphore_acquire", "resource": "main::hs" },
            { "sid": "b3", "kind": "mutex_lock", "resource": "main::m1" },
            { "sid": "b4", "kind": "semaphore_release", "resource": "main::hs" },
            { "sid": "b5", "kind": "mutex_unlock", "resource": "main::m1" },
            { "sid": "b6", "kind": "mutex_unlock", "resource": "main::m2" },
            { "sid": "b7", "kind": "return" }
          ]
        },
        {
          "name": "bystander",
          "kind": "normal",
          "form": "closure",
          "body": [
            { "sid": "y1", "kind": "mutex_lock", "resource": "main::m1" },
            { "sid": "y2", "kind": "mutex_unlock", "resource": "main::m1" },
            { "sid": "y3", "kind": "goto", "target": "y1" }
          ]
        }
      ]
    }
  ]
}
</previous_candidate>

